typedef enum krw_setup_path {
  KRW_SETUP_PATH_VOUCHER = 0,
  KRW_SETUP_PATH_PORTS_VM = 1,
  KRW_SETUP_PATH_IOSURFACE = 2,
  KRW_SETUP_PATH_IOGPU = 3,
} krw_setup_path_t;

